def main():
    data = base64.b85decode(PAYLOAD)
    if hashlib.sha256(data).hexdigest() != PAYLOAD_SHA256:
        raise SystemExit('Embedded audit checksum mismatch')
    parent = Path(__file__).resolve().parent
    folder = Path(tempfile.mkdtemp(prefix='pool_numeric_', dir=str(parent)))
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        for member in archive.infolist():
            parts = PurePosixPath(member.filename).parts
            if len(parts) != 2 or parts[0] != 'joint_pool_numeric_v2' or parts[1] in ('.', '..'):
                raise SystemExit('Invalid embedded audit member')
        archive.extractall(folder)
    entry = folder / 'joint_pool_numeric_v2' / 'audit.py'
    print('TOOL_DIR=' + str(entry.parent), flush=True)
    os.environ['PYTHONDONTWRITEBYTECODE'] = '1'
    os.execv(sys.executable, [sys.executable, '-u', str(entry), *sys.argv[1:]])

if __name__ == '__main__':
    main()
